import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
# find marker column (all same nonzero-const color across rows)
h,w=len(inp),len(inp[0])
mc=None
for c in range(w):
    col={inp[r][c] for r in range(h)}
    if len(col)==1 and c not in (0,w-1): mc=c; print('marker col',c,col)
L=[row[:mc] for row in inp]; R=[row[mc+1:mc+1+(w-mc-1)- (w-mc-1-len(row[:mc]))] for row in inp]
R=[row[mc+1:mc+1+len(L[0])] for row in inp]
print(len(L[0]),len(R[0]))
match=[[3 if L[r][c]==R[r][c] else 8 for c in range(len(L[0]))] for r in range(h)]
print(match==out)
# test input
T=G['Test input']; h2,w2=len(T),len(T[0])
mc2=None
for c in range(w2):
    col={T[r][c] for r in range(h2)}
    if len(col)==1: mc2=c; print('test marker col',c,col)
L2=[row[:mc2] for row in T]; R2=[row[mc2+1:mc2+1+mc2] for row in T]
print(len(L2[0]),len(R2[0]))
pred=[[3 if L2[r][c]==R2[r][c] else 4 for c in range(len(L2[0]))] for r in range(h2)]
import json; print(json.dumps(pred))

